/** True when this account can actually be charged off-session right now. */
export function hasChargeableCard(user: {
  stripeCustomerId: string | null;
  stripePaymentMethodId: string | null;
}): boolean {
  return stripeConfigured() && !!user.stripeCustomerId && !!user.stripePaymentMethodId;
}

