"use server";

import { placeHostingOrder } from "@/lib/actions-hosting";
import { orderEmailHosting } from "@/lib/actions-email-hosting";

/* Form adapters for the two products whose order functions are not FormData-shaped.
 *
 * `payAndDeploy`, `payAndDeployGame` and `purchaseDomain` all take
 * `(prev, formData)`, so the wizard posts hidden fields straight to them.
 * `orderHostingAccount` and `orderEmailHosting` take POSITIONAL arguments, so
 * they need something between the form and the function.
 *
 * THE RULE FOR EVERYTHING IN THIS FILE: it translates, it does not decide.
 * No pricing, no eligibility, no wallet arithmetic, no validation beyond
 * reading strings out of a FormData. Every one of those already lives inside
 * the real function — impersonation refusal, the email-verification gate, the
 * domain-uniqueness check, the wallet/card split — and a second copy here would
 * be a second set of rules guarding the same money, free to drift.
 *
 * Both exports are network-callable (`"use server"` makes every export so), and
 * both are spend paths. That is acceptable ONLY because each is a thin call into
 * a function that does its own authorisation. Do not add anything here that
 * authorises, prices, or charges on its own.
 */

export type SubmitState = { error?: string; ok?: boolean; checkout?: { clientSecret: string; publishableKey: string } };

/** Place a shared-hosting order from the wizard's form. */
export async function submitHosting(_prev: SubmitState, formData: FormData): Promise<SubmitState> {
  /* `placeHostingOrder`, NOT `orderHostingAccount`.
   *
   * They are not variants of one another. `orderHostingAccount` takes no
   * `useWallet` argument at all, so it ALWAYS spends the balance when the
   * balance covers the cost — which means it always places the order and never
   * yields a Stripe session. The wizard's "use account balance" toggle had
   * nowhere to send its value, the card fields could therefore never appear for
   * hosting, and calling it to obtain a session instead created a real account
   * every time (200 of them, in this sandbox, before it hit the node's cap).
   *
   * `placeHostingOrder` is the wallet-aware entry point: it honours the toggle,
   * returns `{ checkout }` when a card leg is due WITHOUT placing anything, and
   * only commits when the balance actually covers the total. Everything else —
   * pricing, the promo claim, the hostname claim, the impersonation and
   * email-verification gates — stays inside it. */
  const res = await placeHostingOrder({
    planId: String(formData.get("planId") ?? ""),
    domain: String(formData.get("domain") ?? "").trim() || undefined,
    subdomainLabel: String(formData.get("subdomainLabel") ?? "").trim() || undefined,
    termMonths: Number(formData.get("termMonths") ?? 1),
    extraDiskGB: Number(formData.get("extraDiskGB") ?? 0) || undefined,
    idempotencyKey: String(formData.get("idempotencyKey") ?? ""),
    /* Only an explicit "0" declines the balance, matching the action's own
       default rather than re-deciding it here. */
    useWallet: formData.get("useWallet") !== "0",
  });

  if ("error" in res) return { error: res.error };
  if ("needCard" in res) {
    return { error: "Add a payment card to your account first — this plan renews automatically." };
  }
  if ("checkout" in res) return { checkout: res.checkout };
  return { ok: true };
}

/** Place a business-email order from the wizard's form. */
export async function submitEmail(_prev: SubmitState, formData: FormData): Promise<SubmitState> {
  const domainName = String(formData.get("domain") ?? "").trim();
  const emailPlanId = String(formData.get("planId") ?? "");
  const termMonths = Number(formData.get("termMonths") ?? 1);
  // Defaults ON, and only an explicit "0" turns it off — matching the real
  // function's own default rather than re-deciding it here.
  const useWallet = formData.get("useWallet") !== "0";

  const res = await orderEmailHosting(domainName, emailPlanId, termMonths, useWallet);
  /* Error first: a result carrying BOTH would otherwise be reported as a
     checkout to mount rather than a problem to show. */
  if ("error" in res && res.error) return { error: res.error };
  if ("checkout" in res && res.checkout) return { checkout: res.checkout };
  return { ok: true };
}
