export async function payAndDeployGame(
  _prev: unknown,
  formData: FormData,
): Promise<{ error?: string; checkout?: EmbeddedCheckout }> {
  const user = await requireUser();
  // Spend path: never move a customer's money while an admin is impersonating them.
  // Caught so an impersonating admin sees this message inline instead of a page
  // crash — the bare throw used to hit the wizard's generic error screen on
  // every payment attempt.
  try {
    await assertNotImpersonating();
  } catch (e) {
    return { error: e instanceof Error ? e.message : "This action is disabled while impersonating a customer." };
  }
  // Purchase gate: an unverified address means we cannot reach the person we are
  // about to charge (see lib/email-verification.ts). Consulted before any money moves.
  const unverified = await emailVerificationError(user);
  if (unverified) return { error: unverified };
  const gateErr = await gameOrderGate(user);
  if (gateErr) return { error: gateErr };

  let intent = gameIntentFromFormData(formData);

  let quote;
  try {
    quote = await gameOrderQuote(intent, { userId: user.id });
    // Region decided + capacity-checked BEFORE any charge; a full region
    // refuses here with the nearest alternatives (never silently overflows).
    intent = await resolveGameIntentRegion(intent, quote, user.id);
  } catch (e) {
    if (e instanceof GameOrderError) return { error: e.message };
    throw e;
  }

  // The DB-fed term price, net of any valid coupon discount. No VAT for game.
  const chargeCents = quote.chargeCents;

  // Wallet-aware split — the wizard computes the identical split (lib/wallet-split.ts)
  // from the same inputs, so what the customer sees === what we charge. `useWallet`
  // defaults ON (only "0" turns it off).
  const useWallet = formData.get("useWallet") !== "0";
  let { cardCents } = walletSplit({ dueCents: chargeCents, balanceCents: user.balanceCents, useWallet });

  // Card portion is $0 (the wallet covers the whole charge) → provision straight
  // away through the audited debit. `placeGameOrder` debits the FULL chargeCents
  // from the wallet; its balance check holds because cardCents <= 0 means the
  // balance already covers the charge.
  if (cardCents <= 0) {
    let serverId: string;
    try {
      serverId = await placeGameOrder(user, intent, null);
    } catch (e) {
      if (e instanceof GameOrderError) return { error: e.message };
      throw e;
    }
    // Wallet-only is still a real payment — same `?purchase=1` marker the card/
    // Stripe path gets via reportPurchase, so ProvisioningOverlay's "just paid"
    // success screen shows for this path too.
    redirect(`/dashboard/servers/${serverId}?purchase=1`);
  }

  // Card leg > 0: if a coupon actually discounted this quote, take an EXCLUSIVE
  // hold on it BEFORE the Checkout session is created — mirrors lib/actions.ts's
  // VPS card path exactly (reserveOrderCoupon), and closes a real gap: without
  // this, a card-paid game order's Stripe session was stamped straight from the
  // quote with no per-person/exclusion check ever run on the card leg, so an
  // EXCLUDED account (excludeActiveCustomers/firstTimeOnly) whose coupon
  // happened to pass the earlier catalog-level checks would actually be
  // CHARGED the discounted price via Stripe — a real undercharge, not just a
  // misleading preview. A lost hold drops the coupon and re-quotes at full
  // price so the stamped total, card leg and settlement all agree (never a
  // discounted leg without a backing hold — displayed === charged).
  let checkoutIntent = intent;
  let couponReservationToken: string | null = null;
  if (quote.couponId && quote.couponDiscountCents > 0) {
    const ipHash = hashIp(clientIp(await headers()), process.env.AUTH_SECRET ?? "nxeon") || null;
    const reservedUntil = new Date(Date.now() + ORDER_CHECKOUT_EXPIRES_MS + RESERVATION_GRACE_MS);
    const res = await reserveOrderCoupon({
      couponId: quote.couponId,
      maxRedemptions: quote.couponMaxRedemptions,
      firstTimeOnly: quote.couponFirstTimeOnly,
      excludeActiveCustomers: quote.couponExcludeActiveCustomers,
      userId: user.id,
      ipHash,
      amountCents: quote.couponDiscountCents,
      reservedUntil,
    });
    if (res.reserved) {
      couponReservationToken = res.token;
    } else {
      checkoutIntent = { ...intent, couponCode: undefined };
      try {
        quote = await gameOrderQuote(checkoutIntent, { userId: user.id });
      } catch (e) {
        if (e instanceof GameOrderError) return { error: e.message };
        throw e;
      }
      ({ cardCents } = walletSplit({ dueCents: quote.chargeCents, balanceCents: user.balanceCents, useWallet }));
    }
  }

  // Card leg > 0 → charge ONLY the remainder on the card. On payment success the
  // confirm/webhook route credits this card amount to the wallet and THEN
  // placeGameOrder debits the full chargeCents, so the wallet naturally absorbs the
  // applied balance and the card the rest — the wallet is never touched before the
  // card clears. The SOLD price is handed over EXPLICITLY (stamped before any
  // charge), so a rate change between now and fulfilment can't re-price it.
  const sold: GameOrderPrice = {
    chargeCents: quote.chargeCents,
    partnerDiscountCents: quote.partnerDiscountCents,
    partnerDiscountTier: quote.partnerDiscountTier,
  };
  let checkout: EmbeddedCheckout | null;
  try {
    checkout = await createGameOrderPaymentSession(user, cardCents, checkoutIntent, sold, couponReservationToken);
  } catch (e) {
    if (e instanceof GameOrderError) return { error: e.message };
    throw e;
  }
  if (!checkout) {
    return { error: "Card payments aren't set up yet — top up your wallet to deploy." };
  }
  return { checkout };
}

