  // provision straight away. placeOrder debits the FULL chargeCents from the wallet
  // (or nothing, for a free grant); the balance check inside it holds because a
  // $0 card portion means balance >= chargeCents.
  if (freePath || cardCents <= 0) {
    let serverId: string;
