      ipHash: promoIpHash,
      serviceType: "VPS",
      campaign: promoCampaign,
      chargedCents: quote.chargeCents,
      reservedUntil,
    });
    if (res.reserved) {
      promoReservationToken = res.token;
    } else {
      // Lost the race (this account/IP already holds or redeemed the credit): re-quote
      // at FULL price and recompute the split so the card leg is the real full amount.
      quote = await orderQuote(intent, { suppressPromo: true, userId: user.id });
