/* The deploy wizard's PayPal entry point — ONE export, dispatching to the
 * platform's own per-product PayPal creators.
 *
 * Why this file exists at all: `createOrderPayPalOrder` and
 * `createGameOrderPayPalOrder` take FormData, while the hosting and email ones
 * take typed objects. The wizard has a single PayPal button and needs a single
 * call, so something has to route. This is that something, and — exactly like
 * lib/nx/submit-hosting.ts — IT TRANSLATES, IT DOES NOT DECIDE.
 *
 * Nothing here prices, discounts, validates eligibility, or touches the wallet.
 * Every one of those already lives inside the action being called: each re-quotes
 * server-side, reserves the promo/coupon, computes `cardCents` after the wallet
 * split, and releases the reservation if PayPal refuses to open. A second copy
 * of any of it here would be a second set of rules guarding the same money.
 *
 * The FormData handed in is the wizard's REAL form, read straight off the
 * <form> element that the card path submits — not a hand-built object. That is
 * deliberate: PayPal and card therefore order byte-for-byte the same thing, and
 * a field added to the form reaches both rails or neither.
 */

export type PayPalService = "vps" | "game" | "hosting" | "email" | "domains";

export async function openWizardPayPalOrder(
  service: PayPalService,
  formData: FormData,
): Promise<CreatePayPalOrderResult> {
  if (service === "vps") return createOrderPayPalOrder(formData);
  if (service === "game") return createGameOrderPayPalOrder(formData);

  if (service === "hosting") {
    return createHostingOrderPayPalOrder({
      planId: String(formData.get("planId") ?? ""),
      domain: String(formData.get("domain") ?? "").trim() || undefined,
      subdomainLabel: String(formData.get("subdomainLabel") ?? "").trim() || undefined,
      termMonths: Number(formData.get("termMonths") ?? 1),
      extraDiskGB: Number(formData.get("extraDiskGB") ?? 0) || undefined,
      // The action de-duplicates on this, so a double-click cannot open two
      // PayPal orders for one basket. Generated per attempt by the caller.
      idempotencyKey: String(formData.get("idempotencyKey") ?? ""),
      useWallet: formData.get("useWallet") !== "0",
    });
  }

  if (service === "email") {
    return createEmailOrderPayPalOrder({
      domainName: String(formData.get("domain") ?? "").trim(),
      emailPlanId: String(formData.get("planId") ?? ""),
      termMonths: Number(formData.get("termMonths") ?? 1),
      useWallet: formData.get("useWallet") !== "0",
    });
  }

  /* Domains are the one product with no PayPal rail on the platform at all —
     `DomainRegisterWizard` says so in its own words, and there is no
     `createDomainPayPalOrder` to call. Said plainly here rather than silently
     routing a domain to the VPS creator, which would open a PayPal order for
     the wrong product. */
  return { error: "PayPal isn't available for domain registrations yet — please pay by card or balance." };
}
