export type CreateLocalOrderPaymentResult =
  | { error: string }
  | { clientSecret: string; publishableKey: string; method: string; usdCents: number; charge: { currency: string; cents: number } };

/** Re-checked server side on EVERY call (the picker hiding a method is not a control). */
async function localMethodGate(method: unknown): Promise<{ error: string } | null> {
  if (!isLocalMethodId(method) || !(await isLocalMethodEnabled(method))) {
    return { error: "That payment method isn't available right now. Please use another." };
  }
  return null;
}

async function openLocalOrderPayment(opts: {
  user: Awaited<ReturnType<typeof requireUser>>;
  method: string;
  /** The card leg the wizard is showing the customer; the server's own figure must equal it. */
  expectedUsdCents: number;
  cardCents: number;
  metadata: Record<string, string>;
  productName: string;
  release?: () => Promise<void>;
}): Promise<CreateLocalOrderPaymentResult> {
  const fail = async (error: string): Promise<{ error: string }> => {
    await opts.release?.();
    return { error };
  };
  if (!isLocalMethodId(opts.method)) return fail("Unknown payment method.");
  // Never open a session for a figure other than the one the customer was shown. A promo or
  // coupon hold held by another open checkout on the same order can make the server's own
  // quote differ from the wizard's; refuse rather than charge a number nobody agreed to.
  if (!Number.isInteger(opts.expectedUsdCents) || opts.expectedUsdCents !== opts.cardCents) {
    return fail("The amount due changed while this payment was being prepared (a discount may be held by another open payment option). Nothing was charged. Please reload this step and try again.");
  }
  try {
    const cfg = await localPaymentConfig();
    const session = await createLocalOrderPaymentSession(opts.user, opts.cardCents, opts.method, cfg, opts.metadata, opts.productName);
    if (!session) return fail("We couldn't start that payment method. Please try another or pay by card.");
    return {
      clientSecret: session.clientSecret,
      publishableKey: session.publishableKey,
      method: opts.method,
      usdCents: opts.cardCents,
      charge: { currency: LOCAL_METHODS[opts.method].chargeCurrency, cents: session.chargeCents },
    };
  } catch (e) {
    // Stripe refusing the method/currency for this account lands here; nothing was charged.
    console.error("[payments] local method order session failed", opts.method, e instanceof Error ? e.message : e);
    return fail("We couldn't start that payment method. Please try another or pay by card.");
  }
}

