import { db } from "@/lib/db";
import { isPartnerRequest } from "@/lib/partner";

export const dynamic = "force-dynamic";

const APP_URL = (process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/$/, "");

/**
 * Build a pre-filled Nxeon wizard URL for a linked user to complete a purchase.
 * Kodely redirects the user's BROWSER to the returned `url`; the SSO handshake has
 * already given them an Nxeon session, so they land straight in the wizard with the
 * shared wallet + Stripe + provisioner behind it (no money-path reimplemented).
 *
 * Body: { userId, product: "domain" | "vps" | "hosting", domain?: string }
 */
export async function POST(req: Request) {
  if (!(await isPartnerRequest(req))) return Response.json({ error: "unauthorized" }, { status: 401 });
  let body: { userId?: string; product?: string; domain?: string };
  try {
    body = await req.json();
  } catch {
    return Response.json({ error: "invalid json" }, { status: 400 });
  }
  if (!body.userId) return Response.json({ error: "userId required" }, { status: 400 });
  const user = await db.user.findUnique({ where: { id: body.userId }, select: { id: true } });
  if (!user) return Response.json({ error: "user not found" }, { status: 404 });

  let path: string;
  switch (body.product) {
    case "domain": {
      const d = typeof body.domain === "string" && /^[a-z0-9.-]+\.[a-z]{2,}$/i.test(body.domain) ? body.domain : "";
      path = d ? `/dashboard/domains?q=${encodeURIComponent(d)}&ref=kodely` : `/dashboard/domains?ref=kodely`;
      break;
    }
    case "vps":
      path = `/dashboard/deploy?product=vps&ref=kodely`;
      break;
    case "hosting":
      // NOT /dashboard/order — that route is a dumb redirect to the VPS wizard
      // regardless of any query param (verified 2026-08-22). The real hosting
      // order flow lives on the unified Deploy hub.
      path = `/dashboard/deploy?product=hosting&ref=kodely`;
      break;
    default:
      return Response.json({ error: "product must be domain | vps | hosting" }, { status: 400 });
  }
  return Response.json({ url: `${APP_URL}${path}` });
}
