export async function payDedicatedOrder(raw: unknown, useWallet = true): Promise<DedicatedPayResult> {
  try {
    try {
      await assertNotImpersonating();
    } catch {
      return { ok: false, error: "Payments are disabled while you are viewing this account as an admin." };
    }
    const { user, previewAll } = await gatedUser();
    const unverified = await emailVerificationError(user);
    if (unverified) return { ok: false, error: unverified };
    if (!checkRateLimit(`dedicated-pay:${user.id}`, { max: 10, windowMs: 10 * 60_000 }).ok) {
      return { ok: false, error: "Too many attempts. Please wait a few minutes and try again." };
    }
    const intent = parseDedicatedIntent(raw);
    if (!intent) return { ok: false, error: "That configuration isn't valid. Please pick again." };
    const q = await quoteDedicatedOrder(intent, user, { previewAll });
    const split = walletSplit({ dueCents: q.money.totalCents, balanceCents: user.balanceCents, useWallet });
    if (split.cardCents <= 0) {
      const { serverId } = await placeDedicatedOrder(user, intent, { previewAll, via: "wallet" });
      return { ok: true, serverId };
    }
    const checkout = await createDedicatedOrderPaymentSession(user, split.cardCents, intent, q.money, `${q.spec.cpu} · ${q.regionLabel}`);
    if (!checkout) return { ok: false, error: "Card payments aren't available right now. Top up your wallet to cover the order instead." };
    return { ok: true, checkout, cardCents: split.cardCents, walletApplied: split.walletApplied };
  } catch (e) {
    if (e instanceof DedicatedOrderError) return { ok: false, error: e.message };
    if (e instanceof Error && e.message === NOT_FOUND) return { ok: false, error: NOT_FOUND };
    return { ok: false, error: "Something went wrong preparing your payment. Nothing was charged. Please try again." };
  }
}
export async function saveCardFromPaymentSession(
  session: Stripe.Checkout.Session,
  userId: string,
