  // Every caller (9 fulfilment paths — order, game order, hosting, email,
  // domain, resize, disk-expand, dedicated IP, plus the generic dispatch)
  // awaits this and then discards a returned `{error}` inside its own
  // `catch { /* best-effort */ }`, so a failure here was completely silent —
  // fulfilment succeeded, no card got saved, and nothing anywhere recorded
  // why. Found live 2026-09-24: 8 real paying customers had a successful
  // Stripe charge and zero saved card, each silently defaulting to the
  // faster "no card on file" dunning/suspend timeline despite having paid by
  // card. Every early return below now logs with the userId, so a repeat is
  // at least visible in the same place the existing catch already logged to
  // (this function's own console.error), not just a return value nobody read.
  // A local payment method (PayNow, GrabPay, ...) is a one-time payment and has no card to
  // keep: nothing to save, and not an error worth logging.
  if (session.metadata?.nxeonLocalPay) return {};
  if (!stripeConfigured()) {
    console.error(`[cards] could not save card for user ${userId}: Stripe not configured`);
    return { error: "Card payments are not configured." };
  }
  try {
    const piRef = session.payment_intent;
    const piId = typeof piRef === "string" ? piRef : (piRef?.id ?? null);
    const customerId =
      typeof session.customer === "string" ? session.customer : (session.customer?.id ?? null);
    if (!piId || !customerId) {
      console.error(
        `[cards] could not save card for user ${userId}: no payment_intent/customer on session ${session.id ?? "?"}`,
      );
      return { error: "No payment intent / customer on the session." };
    }

    const pi = await stripe().paymentIntents.retrieve(piId, { expand: ["payment_method"] });
    const pmRef = pi.payment_method;
    const pmId = typeof pmRef === "string" ? pmRef : (pmRef?.id ?? null);
    if (!pmId) {
      console.error(`[cards] could not save card for user ${userId}: no payment_method on ${piId}`);
      return { error: "No payment method on the payment intent." };
    }
    // Expanded above, so usually already the object; fall back to a retrieve.
    const pm: Stripe.PaymentMethod =
      pmRef && typeof pmRef !== "string" ? pmRef : await stripe().paymentMethods.retrieve(pmId);

    // Make it the customer's default — best-effort, exactly like the setup version;
    // our own `stripePaymentMethodId` is the source of truth for charging.
    await stripe()
      .customers.update(customerId, { invoice_settings: { default_payment_method: pmId } })
      .catch(() => {
        /* non-fatal */
      });
    const recorded = await persistCard(userId, customerId, pm);
    if (!recorded) return { error: "The payment method on this session is not reusable — not recorded." };

